from dateutil.relativedelta import relativedelta
from datetime import datetime, timedelta
import random
random.seed(2)
base = datetime(2000,1,1)
names = ['days','hours','minutes','seconds','microseconds']
bad=[]
for i in range(5000):
    kw1={}; kw2={}
    for n in names:
        if random.random()<0.5: kw1[n]=round(random.uniform(-10,10), random.choice([0,1,2]))
        if random.random()<0.5: kw2[n]=round(random.uniform(-10,10), random.choice([0,1,2]))
    rd1=relativedelta(**kw1); rd2=relativedelta(**kw2)
    s = rd1 + rd2
    # associativity: (base+rd1)+rd2 vs base+(rd1+rd2)
    a = (base + rd1) + rd2
    b = base + s
    if a != b:
        bad.append((kw1,kw2,repr(s),a,b))
print('assoc mismatches:', len(bad))
for x in bad[:10]: print(x)
