import zlib, os
def read(p):
    d = zlib.decompress(open(p,'rb').read())
    head, body = d.split(b'\x00',1)
    return head.decode(), body
objs = {}
for root, dirs, files in os.walk('objects'):
    for fn in files:
        p = os.path.join(root, fn)
        h = root.split('/')[-1] + fn
        objs[h] = read(p)
def parse_tree(body):
    out=[]
    i=0
    while i < len(body):
        j = body.index(b'\x00', i)
        mode_name = body[i:j].decode()
        mode, name = mode_name.split(' ',1)
        sha = body[j+1:j+21].hex()
        out.append((mode,name,sha))
        i = j+21
    return out
for h,(head,body) in objs.items():
    if head.startswith('tree'):
        print('TREE', h, head)
        for mode,name,sha in parse_tree(body):
            exists = sha in objs
            if name.endswith('.py') or not exists:
                print('   ', mode, name, sha, 'IN-OBJS' if exists else 'missing')
